// Command wordfreq reads standard input and prints the ten most frequent
// ASCII words, one "<count> <word>" line each.
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

const topN = 10

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "wordfreq:", err)
		os.Exit(1)
	}
}

func run() error {
	counts, err := Count(os.Stdin)
	if err != nil {
		return err
	}
	out := bufio.NewWriter(os.Stdout)
	var line []byte
	for _, e := range Top(counts, topN) {
		line = strconv.AppendInt(line[:0], int64(e.Count), 10)
		line = append(line, ' ')
		line = append(line, e.Word...)
		line = append(line, '\n')
		if _, err := out.Write(line); err != nil {
			return err
		}
	}
	return out.Flush()
}

package main

import (
	"cmp"
	"errors"
	"io"
	"slices"
	"strings"
)

const readBufferSize = 1 << 16

// Entry is a word together with its number of occurrences.
type Entry struct {
	Word  string
	Count int
}

// Count reads r to EOF and returns the number of occurrences of each word.
// A word is a maximal run of ASCII letters, folded to lowercase; every other
// byte is a separator.
func Count(r io.Reader) (map[string]int, error) {
	counts := make(map[string]int)
	buf := make([]byte, readBufferSize)
	word := make([]byte, 0, 64)
	for {
		n, err := r.Read(buf)
		for _, b := range buf[:n] {
			// Setting bit 0x20 maps 'A'..'Z' onto 'a'..'z' and leaves
			// lowercase letters unchanged; no other byte lands in 'a'..'z'.
			if lower := b | 0x20; lower >= 'a' && lower <= 'z' {
				word = append(word, lower)
			} else if len(word) > 0 {
				counts[string(word)]++
				word = word[:0]
			}
		}
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	if len(word) > 0 {
		counts[string(word)]++
	}
	return counts, nil
}

// compareEntries orders entries by count descending, then word ascending.
func compareEntries(a, b Entry) int {
	if c := cmp.Compare(b.Count, a.Count); c != 0 {
		return c
	}
	return strings.Compare(a.Word, b.Word)
}

// Top returns at most limit entries from counts, ordered by count descending
// and then by word ascending (byte order).
func Top(counts map[string]int, limit int) []Entry {
	if limit <= 0 {
		return nil
	}
	// Keep a small sorted slice of the best entries seen so far; limit is
	// tiny compared to the number of distinct words.
	top := make([]Entry, 0, limit+1)
	for w, c := range counts {
		e := Entry{Word: w, Count: c}
		if len(top) == limit && compareEntries(e, top[limit-1]) >= 0 {
			continue
		}
		i, _ := slices.BinarySearchFunc(top, e, compareEntries)
		top = slices.Insert(top, i, e)
		if len(top) > limit {
			top = top[:limit]
		}
	}
	return top
}

package main

import (
	"reflect"
	"strings"
	"testing"
)

func TestCountAndTop(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  []Entry
	}{
		{"empty", "", nil},
		{"no words", "123 _ ' \xff\xc3(", nil},
		{"simple", "The cat and the hat.", []Entry{{"the", 2}, {"and", 1}, {"cat", 1}, {"hat", 1}}},
		{"separators", "don't stop_me 4now, now-NOW", []Entry{{"now", 3}, {"don", 1}, {"me", 1}, {"stop", 1}, {"t", 1}}},
		{"non-letters near letters", "a@b[c`d{e\x80f\xc1g", []Entry{{"a", 1}, {"b", 1}, {"c", 1}, {"d", 1}, {"e", 1}, {"f", 1}, {"g", 1}}},
		{"top ten", "zeta eta theta iota kappa lambda mu nu xi omicron pi rho alpha beta alpha", []Entry{
			{"alpha", 2}, {"beta", 1}, {"eta", 1}, {"iota", 1}, {"kappa", 1},
			{"lambda", 1}, {"mu", 1}, {"nu", 1}, {"omicron", 1}, {"pi", 1},
		}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			counts, err := Count(strings.NewReader(tt.input))
			if err != nil {
				t.Fatal(err)
			}
			got := Top(counts, 10)
			if len(got) == 0 && len(tt.want) == 0 {
				return
			}
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf("got %v, want %v", got, tt.want)
			}
		})
	}
}

func TestCountAcrossReadBoundary(t *testing.T) {
	input := strings.Repeat(" ", readBufferSize-2) + "Word word"
	counts, err := Count(strings.NewReader(input))
	if err != nil {
		t.Fatal(err)
	}
	if got := counts["word"]; got != 2 || len(counts) != 1 {
		t.Errorf("counts = %v, want map[word:2]", counts)
	}
}
